using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
namespace DoomSNESed {
    public sealed class TextReplacement {public int Id;public string Text;public List<CreditLine> Lines;}
    public sealed class CreditLine {public int Record,Column,Row;public string Text;}
    public static class TextAssets {
        public static readonly int[] StoryStart={0,0x1f5ec6,0x1f609b,0x1f628a};
        public static readonly int[] StorySize={0,469,495,531};
        public const int Credits=0x1ff0a8,CreditCount=41;
        public static string Story(byte[] rom,int episode){var lines=new SortedDictionary<int,string>();int p=RomLayout.At(rom,StoryStart[episode]),row=0;while(rom[p]!=255){Bin.Require(rom[p++]==0,"Invalid original ending text.");int dest=Bin.U16(rom,p);p+=2;row=(dest-0x7800)/32-4;int start=p;while(rom[p]!=0&&rom[p]!=255)p++;lines[row]=Encoding.ASCII.GetString(rom,start,p-start);}int max=lines.Keys.Max();return string.Join("\r\n",Enumerable.Range(0,max+1).Select(i=>lines.ContainsKey(i)?lines[i]:"").ToArray());}
        public static int StoryCapacity(byte[] rom,int episode){return rom!=null&&RomLayout.SourceBuilt(rom)&&episode==3?23:StorySize[episode];}
        public static byte[] EncodeStory(int episode,string text,byte[] rom=null){Bin.Require(episode>=1&&episode<=3,"Unknown ending.");string[] lines=(text??"").Replace("\r","").Split('\n');Bin.Require(lines.Length<=24,"Ending text has at most 24 rows below its 4-row top margin.");var bytes=new List<byte>();for(int row=0;row<lines.Length;row++){string line=lines[row];Bin.Require(line.Length<=30,"Ending row "+(row+1)+" exceeds 30 characters. Use Wrap text.");Bin.Require(line.All(c=>c>=32&&c<=126),"Use characters in the ROM font (ASCII space through ~).");if(line.Length==0)continue;bytes.Add(0);int address=0x7800+(row+4)*32+1;bytes.Add((byte)address);bytes.Add((byte)(address>>8));bytes.AddRange(Encoding.ASCII.GetBytes(line));}bytes.Add(255);Bin.Require(bytes.Count<=StoryCapacity(rom,episode),"Ending text needs "+bytes.Count+" bytes; Episode "+episode+" has "+StoryCapacity(rom,episode)+". Shorten the text or remove lines.");return bytes.ToArray();}
        public static List<CreditLine> ReadCredits(byte[] rom,int page){var lines=new List<CreditLine>();for(int i=0;i<CreditCount;i++){int entry=RomLayout.At(rom,Credits)+i*6,dest=Bin.U16(rom,entry);if((dest>=0x7400?2:1)!=page)continue;int offset=dest-(page==1?0x7000:0x7400);lines.Add(new CreditLine{Record=i,Row=offset/32,Column=offset%32,Text=Encoding.ASCII.GetString(rom,GraphicsAssets.Address(rom,entry+2),rom[entry+5])});}return lines;}
        public static void ValidateCredit(CreditLine line,int page){Bin.Require(line.Record>=0&&line.Record<CreditCount&&page>=1&&page<=2&&line.Row>=0&&line.Row<28&&line.Column>=0&&line.Column<32,"Invalid credits layout.");Bin.Require(line.Text!=null&&line.Text.Length<=32-line.Column&&line.Text.All(c=>c>=32&&c<=126),"Credits must fit the row (32 minus its column), using ASCII font characters.");}
        public static void Apply(Rom rom,byte[] target,List<Section> free){if(rom.Project.Texts==null)return;int used=0;foreach(var replacement in rom.Project.Texts){if(replacement.Id==6){CopyrightAssets.Apply(rom,target,replacement,free,ref used);continue;}if(replacement.Id<=3){byte[] encoded=EncodeStory(replacement.Id,replacement.Text,rom.Bytes);for(int i=0;i<StoryCapacity(rom.Bytes,replacement.Id);i++)target[RomLayout.At(target,StoryStart[replacement.Id])+i]=255;Buffer.BlockCopy(encoded,0,target,RomLayout.At(target,StoryStart[replacement.Id]),encoded.Length);}else{int page=replacement.Id-3;var original=ReadCredits(rom.Bytes,page);Bin.Require(replacement.Lines!=null&&replacement.Lines.Count==original.Count&&replacement.Lines.Select(l=>l.Record).Distinct().Count()==original.Count,"Credits must retain the native row count; blank rows with an empty string.");foreach(var line in replacement.Lines){ValidateCredit(line,page);Bin.Require(original.Any(o=>o.Record==line.Record),"Credits row belongs to another page.");byte[] bytes=Encoding.ASCII.GetBytes(line.Text.Length==0?" ":line.Text);int address=GraphicsAssets.Store(target,bytes,free,ref used),p=RomLayout.At(target,Credits)+line.Record*6;Bin.W16(target,p,(page==1?0x7000:0x7400)+line.Row*32+line.Column);Bin.W16(target,p+2,address);target[p+4]=GraphicsAssets.CpuBank(address);target[p+5]=(byte)bytes.Length;}}}rom.Budget.Graphics+=used;}
        public static Bitmap Preview(Rom rom,int id,TextReplacement replacement,List<GraphicReplacement> graphics){int screen=id<=3?id+2:2;var change=graphics.FirstOrDefault(g=>g.Screen==screen);var bitmap=change==null?ScreenAssets.Original(rom,screen):ScreenAssets.Preview(change);for(int y=0;y<bitmap.Height;y++)for(int x=0;x<bitmap.Width;x++){Color c=bitmap.GetPixel(x,y);bitmap.SetPixel(x,y,Color.FromArgb(c.R/2,c.G/2,c.B/2));}var fontChange=graphics.FirstOrDefault(g=>g.Screen==6);byte[] font=fontChange==null?HudAssets.Data(rom.Bytes,6):HudAssets.Tiles(fontChange);if(id<=3){string[] lines=(replacement==null?Story(rom.Bytes,id):replacement.Text??"").Replace("\r","").Split('\n');for(int row=0;row<Math.Min(24,lines.Length);row++)Draw(bitmap,font,lines[row],8,(row+4)*8);}else{var lines=replacement==null?ReadCredits(rom.Bytes,id-3):replacement.Lines;foreach(var line in lines)Draw(bitmap,font,line.Text,line.Column*8,line.Row*8);}return bitmap;}
        static void Draw(Bitmap bitmap,byte[] font,string text,int px,int py){for(int c=0;c<text.Length;c++){int tile=text[c]-32;if(tile<0||tile*32+31>=font.Length)continue;for(int y=0;y<8;y++)for(int x=0;x<8;x++){int index=0;for(int plane=0;plane<4;plane++)index|=((font[tile*32+(plane/2)*16+y*2+plane%2]>>(7-x))&1)<<plane;int dx=px+c*8+x,dy=py+y;if(index!=0&&dx>=0&&dy>=0&&dx<256&&dy<224)bitmap.SetPixel(dx,dy,index==7?Color.Black:Color.FromArgb(239,239,239));}}}
        public static string Wrap(string text){var rows=new List<string>();foreach(string paragraph in text.Replace("\r","").Split('\n')){string row="";foreach(string word in paragraph.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries)){string remaining=word;if(row.Length>0&&row.Length+1+word.Length>30){rows.Add(row);row="";}while(remaining.Length>30){if(row.Length>0){rows.Add(row);row="";}rows.Add(remaining.Substring(0,30));remaining=remaining.Substring(30);}row+=(row.Length==0?"":" ")+remaining;}rows.Add(row);}return string.Join("\r\n",rows.ToArray());}
    }
}


